16	function case_data = task005_load_case(fixture_path)
17	if exist(fixture_path, 'file') ~= 2
18	    error('sciencebench:task005:FixtureMissing', 'Public fixture not found: %s', fixture_path);
19	end
20	
21	decoded = jsondecode(fileread(fixture_path));
22	scalar_fields = {
23	    'num_points', 'ppm_min', 'ppm_max', 'reference_center_ppm', ...
24	    'reference_width_ppm', 'edited_center_ppm', 'edited_width_ppm'
25	};
26	for idx = 1:numel(scalar_fields)
27	    field_name = scalar_fields{idx};
28	    if ~isfield(decoded, field_name)
29	        error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: %s', field_name);
30	    end
31	    value = decoded.(field_name);
32	    if ~isnumeric(value) || numel(value) ~= 1 || ~isfinite(value)
33	        error('sciencebench:task005:FixtureProtocol', 'Fixture field %s must be one finite number.', field_name);
34	    end
35	    case_data.(field_name) = double(value);
36	end
37	
38	if ~isfield(decoded, 'name')
39	    error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: name');
40	end
41	case_data.name = char(decoded.name);
42	
43	vector_fields = {'reference_amplitudes', 'edited_amplitudes', 'phase_degrees'};
44	for idx = 1:numel(vector_fields)
45	    field_name = vector_fields{idx};
46	    if ~isfield(decoded, field_name)
47	        error('sciencebench:task005:FixtureProtocol', 'Missing fixture field: %s', field_name);
48	    end
49	    value = double(decoded.(field_name));
50	    if ~isnumeric(value) || isempty(value) || any(~isfinite(value(:)))
51	        error('sciencebench:task005:FixtureProtocol', 'Fixture field %s must contain finite numbers.', field_name);
52	    end
53	    case_data.(field_name) = reshape(value, 1, []);
54	end
55	
56	nsubs = numel(case_data.reference_amplitudes);
57	if numel(case_data.edited_amplitudes) ~= nsubs || numel(case_data.phase_degrees) ~= nsubs
58	    error('sciencebench:task005:FixtureProtocol', 'Fixture subspectrum arrays must have equal lengths.');
59	end
60	if case_data.num_points < 16 || case_data.ppm_max <= case_data.ppm_min
61	    error('sciencebench:task005:FixtureProtocol', 'Fixture spectral grid is invalid.');
62	end
63	if case_data.reference_width_ppm <= 0 || case_data.edited_width_ppm <= 0
64	    error('sciencebench:task005:FixtureProtocol', 'Fixture peak widths must be positive.');
65	end
66	end
67	
68	function [ppm, spectra] = task005_build_spectra(case_data)
69	npts = case_data.num_points;
70	ppm = linspace(case_data.ppm_min, case_data.ppm_max, npts)';
71	reference_shape = exp(-0.5 .* ((ppm - case_data.reference_center_ppm) ./ case_data.reference_width_ppm) .^ 2);
72	edited_shape = exp(-0.5 .* ((ppm - case_data.edited_center_ppm) ./ case_data.edited_width_ppm) .^ 2);
73	
74	nsubs = numel(case_data.reference_amplitudes);
75	spectra = zeros(npts, nsubs);
76	for idx = 1:nsubs
77	    phase = case_data.phase_degrees(idx) * pi / 180;
78	    signal = case_data.reference_amplitudes(idx) .* reference_shape + ...
79	        case_data.edited_amplitudes(idx) .* edited_shape;
80	    spectra(:, idx) = real(signal .* complex(cos(phase), sin(phase)));
81	end
82	end
83	
84	function metrics = task005_observe_spectra(ppm, spectra, case_data)
85	mask = task005_reference_mask(ppm, case_data.reference_center_ppm, case_data.reference_width_ppm);
86	window = real(spectra(mask, :));
87	
88	polarities = zeros(1, columns(window));
89	for idx = 1:columns(window)
90	    polarities(idx) = task005_estimate_polarity(window(:, idx));
91	end
92	sign_consistency = mean(polarities == polarities(1));
93	
94	norms = zeros(1, columns(window));
95	for idx = 1:columns(window)
96	    norms(idx) = norm(window(:, idx));
97	end
98	retained = norm(mean(window, 2)) / max(mean(norms), 1e-12);
99	
100	metrics.reference_sign_consistency = sign_consistency;
101	metrics.retained_common_signal_ratio = retained;
102	metrics.reference_peak_polarity_consistent = all(polarities == polarities(1));
103	metrics.observations_finite = isfinite(sign_consistency) && isfinite(retained);
104	end
105	
106	function mask = task005_reference_mask(ppm, center, width)
107	mask = abs(ppm - center) <= max(width * 3.5, 0.08);
108	end
109	
110	function polarity = task005_estimate_polarity(spec)
111	[~, idx] = max(abs(real(spec)));
112	if real(spec(idx)) >= 0
113	    polarity = 1.0;
114	else
115	    polarity = -1.0;
116	end
117	end
