165	function data_path = task005_write_loader_fixture(input_dir, spectra)
166	data_path = fullfile(input_dir, 'public_loader.sdat');
167	spar_path = fullfile(input_dir, 'public_loader.spar');
168	
169	samples = rows(spectra);
170	subspecs = columns(spectra);
171	averages_per_subspec = 2;
172	rows_in_file = subspecs * averages_per_subspec;
173	source_fids = ifft(ifftshift(spectra, 1), [], 1);
174	fid_data = zeros(samples, rows_in_file);
175	for average_index = 1:averages_per_subspec
176	    for subspec_index = 1:subspecs
177	        row_index = (average_index - 1) * subspecs + subspec_index;
178	        fid_data(:, row_index) = source_fids(:, subspec_index);
179	    end
180	end
181	
182	packed = zeros(2, samples, rows_in_file);
183	packed(1, :, :) = real(fid_data);
184	packed(2, :, :) = imag(fid_data);
185	
186	fid = fopen(data_path, 'w', 'ieee-le');
187	if fid < 0
188	    error('Could not create public loader fixture.');
189	end
190	fwriteVAXG(fid, packed(:), 'float32');
191	fclose(fid);
192	
193	fid = fopen(spar_path, 'w');
194	if fid < 0
195	    error('Could not create public loader metadata.');
196	end
197	fprintf(fid, 'samples : %d\n', samples);
