1	%io_loadspec_sdat.m
2	%Jamie Near, McGill University 2014.
3	%Georg Oeltzschner, Johns Hopkins University 2018.
4	%
5	% USAGE:
6	% out=io_loadspec_sdat(filename,subspecs);
7	% 
8	% DESCRIPTION:
9	% Reads in Philips MRS data (.spar and .sdat files) using code adapted from 
10	% PhilipsRead.m, provided as part of the Gannet software package by Richard 
11	% Edden (gabamrs.com).
12	% 
13	% io_loadspec_sdat outputs the data in structure format, with fields 
14	% corresponding to time scale, fids, frequency scale, spectra, and header 
15	% fields containing information about the acquisition.  The resulting 
16	% matlab structure can be operated on by the other functions in this MRS 
17	% toolbox. ALSO:  This code is not currently smart enough to parse out all 
18	% of the relevant information from the header file, such as the number of 
19	% subspectra.  So for now, these details must be passed to the function as 
20	% input arguments.  Help implementing these improvements are most welcome!!
21	% 
22	% INPUTS:
23	% filename   = filename of Philips sdat file to be loaded.
24	% subspecs   = number of subspectra in the data (from spectral editing, ISIS, etc.)
25	%
26	% OUTPUTS:
27	% out        = Input dataset in FID-A structure format.
28	
29	function out = io_loadspec_sdat(filename,subspecs,series)
30	
31	if nargin<3
32	    series = 0;
33	end
34	% Read in the data and header information
35	[data, header] = philipsLoad(filename);
36	
37	% Determine the dimensions of the data
38	data_size       = size(data);
39	dims.t          = find(data_size == header.samples);
40	if (header.rows > 1 && header.averages > 1) && series
41	    if length(data_size) > 2 % Data has averages and series
42	        dims.averages   = find(data_size == header.averages);
43	        dims.extras   = find(data_size == header.rows);
44	    else % Data has a series stored
45	        dims.averages   = 0;
46	        dims.extras   = find(data_size == header.rows);
47	    end
48	else
49	    dims.averages   = find(data_size == header.rows);
50	end
51	dims.coils      = 0; % SDAT is already coil-combined
52	% Now arrange in the standard order (samples-avgs-subspecs):
53	if (isfield(header, 'nr_of_slices_for_multislice') && header.nr_of_slices_for_multislice > 1) && (isfield(header, 'dim2_pnts') && header.dim2_pnts' > 1)
54	    data = permute(data ,[dims.t dims.averages dims.Zvoxels]);  
55	    dims.Zvoxels = 3;
56	    dims.averages = 2;
57	    dims.extras = 0;
58	else if (header.rows > 1 && header.averages > 1) && series
59	        if length(data_size) > 2 % Data has averages and series
60	            data = permute(data ,[dims.t dims.extras dims.averages]);
61	            dims.averages = 2;
62	            dims.extras = 3;
63	        else % Data has a series stored
64	            data = permute(data ,[dims.t dims.extras]);
65	            dims.averages = 0;
66	            dims.extras = 2;
67	        end
68	    else
69	        data = permute(data ,[dims.t dims.averages]);
70	        dims.averages = 2;
71	        dims.extras = 0;
72	    end
73	end
74	
75	dims.t = 1;
76	
77	
78	% We have no way of actually knowing the number of sub-spectra (e.g. for 
79	% MEGA-PRESS or HERMES acquisitions, so we will split the averages 
80	% according to the 'subspecs' input.
81	% Initialize fids array:
82	fids = squeeze(zeros(header.samples, header.rows/subspecs, subspecs));
83	% Remove phase cycle
84	fids = fids .* repmat(conj(fids(1,:,:,:))./abs(fids(1,:,:,:)),[size(fids,1) 1]);
85	if subspecs == 2
86	    %Split the subspectra out of the "averages" dimension:
87	    fids(:,:,1) = data(:,[1:2:end]);
88	    fids(:,:,2) = data(:,[2:2:end]);
89	elseif subspecs == 4
90	    fids(:,:,1) = data(:,[1:4:end]);
91	    fids(:,:,2) = data(:,[2:4:end]);
92	    fids(:,:,3) = data(:,[3:4:end]);
93	    fids(:,:,4) = data(:,[4:4:end]);
94	else
95	    fids = data;
96	end
97	
98	if subspecs > 1
99	    dims.subSpecs = 3;
100	else
101	    dims.subSpecs = 0;
102	end
103	
104	sz = size(fids);
105	
106	% Fill in the header information
107	txfrq = header.synthesizer_frequency; % transmitter frequency [Hz]
108	Bo = txfrq/42577000; % B0 [T]
109	averages = size(fids,2)*size(fids,3); % number of rows in the file
110	rawAverages = averages;
111	spectralwidth = header.sample_frequency; % bandwidth [Hz]
112	dwelltime = 1/spectralwidth; % dwelltime [s]
113	te = header.echo_time; % echo time [ms]
114	tr = header.repetition_time; % repetition time [ms]
115	sequence = header.scan_id; % sequence type
116	Ncoils = 1; % SDAT already coil-combined
117	rawSubspecs = subspecs;
118	date = header.scan_date; % scan date [yyyy.mm.dd hh:mm:ss]
119	geometry.size.ap = header.ap_size; % voxel size in AP direction [mm]
120	geometry.size.lr = header.lr_size; % voxel size in LR direction [mm]
121	geometry.size.cc = header.cc_size; % voxel size in CC direction [mm]
122	geometry.pos.ap = header.ap_off_center; % voxel center offset in AP direction [mm]
123	geometry.pos.lr = header.lr_off_center; % voxel center offset in LR direction [mm]
124	geometry.pos.cc = header.cc_off_center; % voxel center offset in CC direction [mm]
125	geometry.rot.ap = header.ap_angulation; % angulation around AP axis [deg]
126	geometry.rot.lr = header.lr_angulation; % angulation around LR axis [deg]
127	geometry.rot.cc = header.cc_angulation; % angulation around CC axis [deg]
128	
129	% Produce specs
130	specs = fftshift(fft(fids,[],dims.t),dims.t);
131	% Calculate t and ppm arrays using the calculated parameters:
132	f = [(-spectralwidth/2)+(spectralwidth/(2*sz(1))):spectralwidth/(sz(1)):(spectralwidth/2)-(spectralwidth/(2*sz(1)))];
133	ppm = f/(Bo*42.577);
134	
135	% Philips data assumes the center frequency to be 4.68 ppm:
136	centerFreq = 4.68;
137	ppm=ppm + centerFreq;
138	
139	t = [0:dwelltime:(sz(1)-1)*dwelltime];
140	
141	%FILLING IN DATA STRUCTURE
142	out.fids=fids;
143	out.specs=specs;
144	out.sz=sz;
145	out.ppm=ppm;  
146	out.t=t;    
147	out.spectralwidth=spectralwidth;
148	out.dwelltime=dwelltime;
149	out.txfrq=txfrq;
150	out.date=date;
151	out.dims=dims;
152	out.Bo=Bo;
153	out.averages=averages;
154	out.rawAverages=rawAverages;
155	out.subspecs=subspecs;
156	out.rawSubspecs=rawSubspecs;
157	out.seq=sequence;
158	out.te=te;
159	out.tr=tr;
160	out.pointsToLeftshift=0;
161	out.centerFreq = centerFreq;
162	out.geometry = geometry;
163	if isfield(header,'nucleus')
164	    out.nucleus = header.nucleus;
165	end
166	if isfield(header,'equipment_sw_verions')
167	    out.software = ['R ' header.equipment_sw_verions];
168	end
169	%FILLING IN DATA STRUCUTRE FOR SDAT MRSI
170	if isfield(header, 'dim2_pnts')
171	    out.nXvoxels = header.dim2_pnts;
172	    out.flags.MultiVoxel=1;
173	end
174	if isfield(header, 'dim3_pnts')
175	    out.nYvoxels = header.dim3_pnts;
176	    out.flags.MultiVoxel=1;
177	end
178	if isfield(header, 'nr_of_slices_for_multislice') && isfield(header, 'dim2_pnts');
179	    out.nZvoxels = header.nr_of_slices_for_multislice;
180	    out.flags.MultiVoxel=1;
181	end
182	
183	%FILLING IN THE FLAGS
184	out.flags.writtentostruct=1;
185	out.flags.gotparams=1;
186	out.flags.leftshifted=0;
187	out.flags.filtered=0;
188	out.flags.zeropadded=0;
189	out.flags.freqcorrected=0;
190	out.flags.phasecorrected=0;
191	out.flags.averaged=0;
192	out.flags.addedrcvrs=1;
193	out.flags.subtracted=0;
194	out.flags.writtentotext=0;
195	out.flags.downsampled=0;
196	if out.dims.subSpecs==0
197	    out.flags.isFourSteps=0;
198	else
199	    out.flags.isFourSteps=(out.sz(out.dims.subSpecs)==4);
200	end
201	if dims.extras > 0 % Is a series
202	   out.extras = out.sz(dims.extras);
203	   extra_names = {};
204	   seq = {};
205	   for ex = 1 : out.sz(dims.extras)
206	       extra_names{ex} = ['Exp_' num2str(ex)];
207	       seq{ex} = out.seq;
208	   end
209	   out.extra_names = extra_names;
210	   if dims.averages == 0
211	      out.averages=1;
212	      out.flags.averaged = 1;
213	   end
214	   out.spectralwidth = ones(1,out.extras)*spectralwidth;
215	   out.dwelltime = ones(1,out.extras)*dwelltime;
216	   out.txfrq = ones(1,out.extras)*txfrq;
217	   out.exp_var = ones(1,out.extras);
218	   out.seq = seq;
219	   out.te = ones(1,out.extras)*te;
220	   out.tr = ones(1,out.extras)*tr;
221	   out.pointsToLeftshift = zeros(1,out.extras);
222	   out.centerFreq = ones(1,out.extras)*centerFreq;   
223	   out.flags.isSeries = 1;
224	   out.flags.MultiVoxel=0;
225	end
226	% Add info for niiwrite
227	out.PatientPosition = strrep([header.patient_position ' ' header.patient_orientation],'"','');
228	out.Manufacturer = 'Philips';
229	[~,filename,ext] = fileparts(filename);
230	out.OriginalFile = [filename ext];
231	% Sequence flags
232	out.flags.isUnEdited = 0;
233	out.flags.isMEGA = 0;
234	out.flags.isHERMES = 0;
235	out.flags.isHERCULES = 0;
236	out.flags.isPRIAM = 0;
237	out.flags.isMRSI = 0;
238	%DONE
239

1	function [out] = osp_editSubSpecAlign(varargin)
2	%% [varargout] = osp_editSubSpecAlign(varargin)
3	%   Aligns sub-spectra of (multiplexed) edited MRS data to minimize
4	%   subtraction artefacts.
5	%
6	%   USAGE:
7	%       [outA, outB, outC, outD] = osp_editSubSpecAlign(in, seq, target,unstableWater);
8	%
9	%   INPUTS:
10	%       in        = Input data structure with sub-spectrum A.
11	%       seq       = sequence type
12	%       target     = String. Can be 'GABA' or 'GSH'. (necessary if only two
13	%                    inputs inA and inB are provided)
14	%       unstableWater = Flag for unstable residual water. This ignores
15	%                       water for the optimization and uses Choline instead
16	%
17	%   OUTPUTS:
18	%       outA       = Output following alignment of averages.
19	%       outB       = Output following alignment of averages.
20	%       outC       = Output following alignment of averages. (optional)
21	%       outD       = Output following alignment of averages. (optional)
22	%
23	%   AUTHOR:
24	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-08-15)
25	%       goeltzs1@jhmi.edu
26	%       Dr. Mark Mikkelsen (Johns Hopkins University)
27	%       mmikkel5@jhmi.edu
28	%   
29	%   CREDITS:    
30	%       This code is based on numerous functions from the FID-A toolbox by
31	%       Dr. Jamie Near (McGill University)
32	%       https://github.com/CIC-methods/FID-A
33	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
34	%
35	%   HISTORY:
36	%       2019-08-15: First version of the code.
37	
38	
39	% Determine whether there are 2 (MEGA) or 4 (HERMES/HERCULES) inputs
40	if nargin == 5
41	    in     = varargin{1};
42	    seqType = varargin{2};
43	    target1 = varargin{3};
44	    target2 = varargin{4};
45	    unstableWater = varargin{5};
46	elseif nargin == 4 && (strcmp(varargin{2},'HERMES') || strcmp(varargin{2},'HERCULES'))
47	    in     = varargin{1};
48	    seqType = varargin{2};
49	    target1 = varargin{3};
50	    target2 = varargin{4};
51	    unstableWater = 0;
52	elseif nargin == 4
53	    in     = varargin{1};
54	    seqType = varargin{2};
55	    target = varargin{3};
56	    unstableWater = varargin{4};
57	elseif nargin == 3 && strcmp(varargin{2},'MEGA')
58	    in     = varargin{1};
59	    seqType = varargin{2};
60	    target  = varargin{3};
61	    unstableWater = 0;
62	else
63	    error('Error in osp_editSubSpecAlign! For provide raw data struct, the sequence type, the name of the editing target, and the optional unstable water flag.')
64	end
65	
66	% Check whether data is coil-combined. If not, throw error.
67	if ~in.flags.addedrcvrs
68	    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
69	end
70	
71	% Check whether data is averaged. If not, throw error.
72	if ~in.flags.averaged
73	    error('ERROR:  I think it only makes sense to do this after averaging using op_averaging.  ABORTING!!');
74	end
75	
76	switch seqType
77	   case 'MEGA'
78	        inA=op_takesubspec(in,1);
79	        inB=op_takesubspec(in,2);
80	    case 'HERMES'
81	        inA=op_takesubspec(in,1);
82	        inB=op_takesubspec(in,2);
83	        inC=op_takesubspec(in,3);
84	        inD=op_takesubspec(in,4);
85	    case 'HERCULES'
86	        inA=op_takesubspec(in,1);
87	        inB=op_takesubspec(in,2);
88	        inC=op_takesubspec(in,3);
89	        inD=op_takesubspec(in,4);
90	end
91	        
92	    
93	%%% 1. SET UP REQUIRED VARIABLES %%%
94	% Define the frequency ranges over which water, NAA, and Cho subtraction artefacts
95	% are to be minimized. Also, get a good starting estimate for the frequency
96	% alignment shift by determining the difference between the two maxima in
97	% the respective peak range (water, NAA, or Cho).
98	freq = inA.ppm;
99	% Water
100	freqLim(1,:) = freq <= 4.68+0.22 & freq >= 4.68-0.22;
101	[~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
102	freq2 = freq(freqLim(1,:));
103	maxFreq = freq2(i);
104	for jj = 1:2
105	    tmp(jj,:) = freq <= maxFreq(jj)+0.22 & freq >= maxFreq(jj)-0.22;
106	end
107	freqLim(1,:) = or(tmp(1,:), tmp(2,:));
108	f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
109	x0(1,:) = [f0 0];
110	    
111	% NAA
112	freqLim(2,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
113	peaks = '2.01 ppm (A/B)';
114	switch seqType
115	    case 'HERCULES'
116	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
117	    case 'HERMES'
118	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inC.specs(freqLim(2,:))))]);
119	    case 'MEGA'
120	        [~,i] = max([abs(real(inA.specs(freqLim(2,:)))) abs(real(inB.specs(freqLim(2,:))))]);
121	end
122	freq2 = freq(freqLim(2,:));
123	maxFreq = freq2(i);
124	for jj = 1:2
125	    tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
126	end
127	freqLim(2,:) = or(tmp(1,:), tmp(2,:));
128	f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
129	x0(2,:) = [f0 0];
130	
131	% In case the water peak is not well-behaved and has several peaks we are
132	% possibly detecting several peaks. This will lead to unreasonable shifts
133	% between the sub-spectra. In this case, we use the Choline peak.
134	if unstableWater
135	
136	    freqLim(1,:) = freq <= 3.22+0.09 & freq >= 3.22-0.09;
137	    [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
138	    freq2 = freq(freqLim(1,:));
139	    maxFreq = freq2(i);
140	    for jj = 1:2
141	        tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
142	    end
143	    freqLim(1,:) = or(tmp(1,:), tmp(2,:));
144	    f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
145	    x0(1,:) = [f0 0];
146	
147	end
148	
149	% Optimization options
150	lsqnonlinopts = optimoptions(@lsqnonlin);
151	lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');
152	
153	% Initialize common variables
154	t           = inA.t;
155	
156	
157	%%% 2. PERFORM ALIGNMENT BASED ON SEQUENCE TYPE
158	if strcmp(seqType, 'HERMES') || strcmp(seqType, 'HERCULES') 
159	    if ~(exist('target1','var') && exist('target2','var'))
160	        %Fall back into default HERMES GABA GSH editing
161	        target1 = 'GABA';
162	        target2 = 'GSH';
163	    end
164	    
165	    target = [target1 target2];
166	    switch target
167	        case {'GABAGSH','GABALac','GABAEtOH'}  
168	            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
169	            % minimize the residual water peak in the difference between them.
170	
171	            % Determine normalization factor so that normalized spectra are entered
172	            % into the optimization
173	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
174	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
175	            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
176	            % Apply the calculated frequency/phase adjustment to the inB spectrum
177	            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
178	            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
179	            % Create output
180	            outA = inA;
181	            outB = inB;
182	            outB.fids = fidsB;
183	            outB.specs = specsB;
184	
185	            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
186	            % in the difference between them.
187	            % Determine normalization factor so that normalized spectra are entered
188	            % into the optimization
189	            a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
190	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(2,:), t, x);
191	            param(2,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
192	            % Apply the calculated frequency/phase adjustment to the inC spectrum
193	            fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
194	            specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
195	            % Create output
196	            outC = inC;
197	            outC.fids = fidsC;
198	            outC.specs = specsC;
199	
200	            % Then, align the GABA-ON-GSH-ON spectra to the **corrected** GABA-OFF-GSH-ON
201	            % spectrum - this is something Mark/Georg independently from each other
202	            % found out to work best for HERMES/HERCULES data.
203	
204	            % Find Cho peak and get starting estimate for the frequency shift
205	            freqLim(3,:) = freq <= 3.2+0.09 & freq >= 3.2-0.09;
206	            [~,i] = max([abs(real(outC.specs(freqLim(3,:)))) abs(real(inD.specs(freqLim(3,:))))]);
207	            freq2 = freq(freqLim(3,:));
208	            maxFreq = freq2(i);
209	            for jj = 1:2
210	                tmp(jj,:) = freq <= maxFreq(jj)+0.08 & freq >= maxFreq(jj)-0.08;
211	            end
212	            freqLim(3,:) = or(tmp(1,:), tmp(2,:));
213	            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
214	            x0(3,:) = [f0 0];
215	
216	            % Determine normalization factor so that normalized spectra are entered
217	            % into the optimization
218	            a = max(max([abs(real(outC.specs)) abs(real(inD.specs))]));
219	            fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(3,:), t, x);
220	            param(3,:) = lsqnonlin(fun, x0(3,:), [], [], lsqnonlinopts);
221	            % Apply the calculated frequency/phase adjustment to the inD spectrum
222	            fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
223	            specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);
224	
225	            % Create output
226	            outD = inD;
227	            outD.fids = fidsD;
228	            outD.specs = specsD;
229	        
230	        case 'NAANAAG' 
231	            % For HERMES/HERCULES data, align the GSH-OFF spectra first, i.e.
232	            % minimize the residual water peak in the difference between them.
233	            % NAA
234	            freqLim(1,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
235	            [~,i] = max([abs(real(inA.specs(freqLim(1,:)))) abs(real(inB.specs(freqLim(1,:))))]);
236	            freq2 = freq(freqLim(1,:));
237	            maxFreq = freq2(i);
238	            for jj = 1:2
239	                tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
240	            end
241	            freqLim(1,:) = or(tmp(1,:), tmp(2,:));
242	            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
243	            x0(1,:) = [f0 0];
244	            % Determine normalization factor so that normalized spectra are entered
245	            % into the optimization
246	            a = max(max([abs(real(inA.specs)) abs(real(inB.specs))]));
247	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inB, 1/a), freqLim(1,:), t, x);
248	            param(1,:) = lsqnonlin(fun, x0(1,:), [], [], lsqnonlinopts);
249	            % Apply the calculated frequency/phase adjustment to the inB spectrum
250	            fidsB = inB.fids.*exp(1i*pi*(t'*param(1,1)*2+param(1,2)/180));
251	            specsB = fftshift(fft(fidsB, [], inB.dims.t), inB.dims.t);
252	            % Create output
253	            outA = inA;
254	            outB = inB;
255	            outB.fids = fidsB;
256	            outB.specs = specsB;
257	
258	            % Then, align the GABA-OFF spectra, i.e minimize the residual NAA peak
259	            % in the difference between them.
260	            % Determine normalization factor so that normalized spectra are entered
261	            % into the optimization
262	            a = max(max([abs(real(inA.specs)) abs(real(inC.specs))]));
263	            fun = @(x) objFunc(op_ampScale(inA, 1/a), op_ampScale(inC, 1/a), freqLim(2,:), t, x);
264	            param(2,:) = lsqnonlin(fun, x0(2,:), [], [], lsqnonlinopts);
265	            % Apply the calculated frequency/phase adjustment to the inC spectrum
266	            fidsC = inC.fids.*exp(1i*pi*(t'*param(2,1)*2+param(2,2)/180));
267	            specsC = fftshift(fft(fidsC, [], inC.dims.t), inC.dims.t);
268	            % Create output
269	            outC = inC;
270	            outC.fids = fidsC;
271	            outC.specs = specsC;
272	
273	            % Then, align the GABA-ON-GSH-ON spectra to the **corrected** GABA-OFF-GSH-ON
274	            % spectrum - this is something Mark/Georg independently from each other
275	            % found out to work best for HERMES/HERCULES data.
276	
277	            % Find Cho peak and get starting estimate for the frequency shift
278	            freqLim(3,:) = freq <= 2.01+0.13 & freq >= 2.01-0.13;
279	            [~,i] = max([abs(real(outC.specs(freqLim(3,:)))) abs(real(inD.specs(freqLim(3,:))))]);
280	            freq2 = freq(freqLim(3,:));
281	            maxFreq = freq2(i);
282	            for jj = 1:2
283	                tmp(jj,:) = freq <= maxFreq(jj)+0.13 & freq >= maxFreq(jj)-0.13;
284	            end
285	            freqLim(3,:) = or(tmp(1,:), tmp(2,:));
286	            f0 = (maxFreq(1) - maxFreq(2)) * inA.txfrq*1e-6;
287	            x0(3,:) = [f0 0];
