292	            fun = @(x) objFunc(op_ampScale(outC, 1/a), op_ampScale(inD, 1/a), freqLim(3,:), t, x);
293	            param(3,:) = lsqnonlin(fun, x0(3,:), [], [], lsqnonlinopts);
294	            % Apply the calculated frequency/phase adjustment to the inD spectrum
295	            fidsD = inD.fids.*exp(1i*pi*(t'*param(3,1)*2+param(3,2)/180));
296	            specsD = fftshift(fft(fidsD, [], inD.dims.t), inD.dims.t);
