301	            outD.specs = specsD;
302	    end
303	    % Create output
304	    out = op_mergesubspec(outA,outB,outC,outD);
305	
306	    % Add NIfTI-MRS provenance
307	    % Generate fields for provenance
308	    if unstableWater
309	       peaks = '3.2 ppm (A/B), 2.01 ppm (B/C), 3.2 (C/D)';
310	    else
