181	MRSCont.runtime.Load = time;
182	end

1	% op_takesubspec.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_takesubspec(in,index);
6	% 
7	% DESCRIPTION:
8	% Extract the subspectra with indices corresponding to the 'index' input
9	% array. 
10	% 
11	% INPUTS:
12	% in     = input data in matlab structure format.
13	% index  = vector indicating the indices of the subspectra you would like 
14	%          to extract.
15	%
16	% OUTPUTS:
17	% out    = Output dataset consisting of subspectra indices extracted from 
18	%          the input.
19	
20	function out=op_takesubspec(in,index);
21	
22	if ~isnumeric(index)
23	    index = find(strcmp(in.names,index));
24	    if isempty(index)
25	        index = 1;
26	    end
27	end
28	
29	if in.flags.subtracted && ~strcmp(in.seq, 'SPECIAL')
30	    error('ERROR:  Subspectra have already been combined!  Aborting!');
31	end
32	% in.fids = squeeze(in.fids);
33	if in.dims.subSpecs==0
34	    %Can't take subspec because there are none:
35	    if index > 1
36	        error('ERROR:  There are no subspectra in this dataset!  Aborting!');
37	    else
38	        fids = in.fids;
39	    end
40	elseif in.dims.subSpecs==1
41	    %SHOULD NEVER HAPPEN (Time dimension should always be dim=1)
42	    error('ERROR:  dims.subSpecs==1.  This should never happen!  Aborting!');
43	elseif in.dims.subSpecs==2
44	    fids=in.fids(:,index,:,:,:);
45	elseif in.dims.subSpecs==3;
46	    fids=in.fids(:,:,index,:,:,:);
47	elseif in.dims.subSpecs==4;
48	    fids=in.fids(:,:,:,index,:,:,:);
49	elseif in.dims.subSpecs==5
50	    fids=in.fids(:,:,:,:,index,:,:,:);
51	end
52	
53	%re-calculate Specs using fft
54	specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);
55	
56	%change the dims variables
57	if in.dims.t>in.dims.subSpecs && in.dims.subSpecs ~=0
58	    dims.t=in.dims.t-1;
59	else
60	    dims.t=in.dims.t;
61	end
62	if in.dims.coils>in.dims.subSpecs && in.dims.subSpecs ~=0
63	    dims.coils=in.dims.coils-1;
64	else
65	    dims.coils=in.dims.coils;
66	end
67	if in.dims.averages>in.dims.subSpecs && in.dims.subSpecs ~=0
68	    dims.averages=in.dims.averages-1;
69	else
70	    dims.averages=in.dims.averages;
71	end
72	if in.dims.extras>in.dims.subSpecs && in.dims.subSpecs ~=0
73	    dims.extras=in.dims.extras-1;
74	else
75	    dims.extras=in.dims.extras;
76	end
77	dims.subSpecs=0;
78	
79	%re-calculate the sz variable
80	sz=size(fids);
81	
82	
83	%FILLING IN DATA STRUCTURE
84	out=in;
85	out.fids=fids;
86	out.specs=specs;
87	out.sz=sz;
88	out.dims=dims;
89	if ~out.flags.averaged
90	    try
91	        out.averages = out.sz(out.dims.averages);
92	    catch
93	        out.averages = out.sz(2);
94	    end
95	end
96	out.subspecs=1;
97	if isfield(out, 'names')
98	    out.names = out.names(index);
99	end
100	%FILLING IN THE FLAGS
101	out.flags=in.flags;
102	out.flags.writtentostruct=1;
103	out.flags.isFourSteps=0;
104

1	% op_mergesubspec.m
2	% Helge Zoellner, Johns Hopkins University 2021.
3	% 
4	% USAGE:
5	% out=op_mergesubspec(varargin);
6	% 
7	% DESCRIPTION:
8	% Merges input structs into the subspectra dimension
9	% 
10	% INPUTS:
11	% varargin     = input data in matlab structure format.
12	%
13	% OUTPUTS:
14	% out    = Output dataset with merged subspectra
15	
16	function out=op_mergesubspec(varargin);
17	in1 = varargin{1};
18	
19	if isempty(varargin{2}) %Check if the first argument to be a null string
20	    error('You have to at least put in two structs')
21	else
22	    
23	    for ss = 2 : length(varargin)
24	        in2 = varargin{ss};
25	        if in1.dims.subSpecs~=0 && in2.dims.subSpecs~=0 && in1.dims.subSpecs ~= in2.dims.subSpecs
26	            %RULE:  Averages dimension must be the same for both inputs UNLESS one of
27	            %the inputs has an averages dimension of zero:
28	            error('subspectra dimensions must be the same for both inputs');
29	        end
30	
31	        if in1.dims.subSpecs==0 && in2.dims.subSpecs==0
32	            dim=2;
33	        elseif in1.dims.subSpecs==0
34	            dim=in2.dims.subSpecs;
35	        elseif in2.dims.averages==0;
36	            dim=in1.dims.subSpecs;
37	        else
38	            dim=in1.dims.subSpecs;
39	        end
40	        if ~contains(in1.names,in2.names(1))
41	            in1.fids=cat(dim,in1.fids,in2.fids);
42	            in1.specs=cat(dim,in1.specs,in2.specs);
43	            in1.subspecs=in1.subspecs+in2.subspecs;
44	            in1.names{end+1} = in2.names{1};
45	        else
46	            ind = find(strcmp(in1.names,in2.names(1)));
47	            in1.fids(:,ind,:,:,:,:,:) = in2.fids(:,1,:,:,:,:,:);
48	            in1.specs(:,ind,:,:,:,:,:) = in2.specs(:,1,:,:,:,:,:);
49	        end
50	        
51	    end
52	    sz=size(in1.fids);
53	    
54	    %FILLING IN DATA STRUCTURE
55	    out=in1;
56	    out.sz=sz;
57	%     out.rawAverages=in1.rawAverages+in2.rawAverages;
58	    if in1.dims.subSpecs==0
59	        out.dims.subSpecs=dim;
60	    end
61	    
62	    
63	    %FILLING IN THE FLAGS
64	    out.flags=in1.flags;
65	    out.flags.writtentostruct=1;
66	end
67

1	% op_averaging.m
2	% Jamie Near, McGill University 2014.
3	% 
4	% USAGE:
5	% out=op_averaging(in);
6	% 
7	% DESCRIPTION:
8	% Combine the averages in a scan by adding the averages together and then 
9	% dividing by the number of averages.
10	% 
11	% INPUTS:
12	% in	= input data in matlab structure format.
13	%
14	% OUTPUTS:
15	% out   = Output following averaging.  
16	
17	function out=op_averaging(in);
18	
19	if in.flags.averaged
20	    error('ERROR:  Averaging has already been performed!  Aborting!');
21	end
22	
23	if in.dims.averages==0 || in.averages<2 || (length(in.sz)< in.dims.averages)
24	    %DO NOTHING
25	    warning('Just one average found. Returning input without modification!');
26	    %change the dims variables.
27	    dims.t=in.dims.t;
28	    if in.dims.coils>in.dims.averages
29	        dims.coils=in.dims.coils-1;
30	    else
31	        dims.coils=in.dims.coils;
32	    end
33	    dims.averages=0;
34	    if in.dims.subSpecs>in.dims.averages
35	        dims.subSpecs=in.dims.subSpecs-1;
36	    else
37	        dims.subSpecs=in.dims.subSpecs;
38	    end
39	    if in.dims.extras>in.dims.averages
40	        dims.extras=in.dims.extras-1;
41	    else
42	        dims.extras=in.dims.extras;
43	    end
44	    out=in;
45	    out.dims=dims;
46	    out.flags.averaged=1;
47	else
48	    
49	    %add the spectrum along the averages dimension;
50	    fids=sum(in.fids,in.dims.averages);
51	    fids=squeeze(fids);
52	    fids=fids/in.sz(in.dims.averages); %divide by number of averages;
53	    
54	    %re-calculate Specs using fft
55	    specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);
56	    
57	    %change the dims variables.
58	    if in.dims.t>in.dims.averages
59	        dims.t=in.dims.t-1;
60	    else
61	        dims.t=in.dims.t;
62	    end
63	    if in.dims.coils>in.dims.averages
64	        dims.coils=in.dims.coils-1;
65	    else
66	        dims.coils=in.dims.coils;
67	    end
68	    dims.averages=0;
69	    if in.dims.subSpecs>in.dims.averages
70	        dims.subSpecs=in.dims.subSpecs-1;
71	    else
72	        dims.subSpecs=in.dims.subSpecs;
73	    end
74	    if in.dims.extras>in.dims.averages
75	        dims.extras=in.dims.extras-1;
76	    else
77	        dims.extras=in.dims.extras;
78	    end
79	    
80	    
81	    %re-calculate the sz variable
82	    sz=size(fids);
83	    
84	    % Add NIfTI-MRS provenance
85	    % Generate fields for provenance
86	    fields.Method   = 'Signal averaging';
87	    fields.Details  = ['Classic signal averaging, dim = DIM_DYN'];
88	    in = op_add_analysis_provenance(in,fields);
89	    
90	    %FILLING IN DATA STRUCTURE
91	    out=in;
92	    out.fids=fids;
93	    out.specs=specs;
94	    out.sz=sz;
95	    out.dims=dims;
96	    out.averages=1;
97	    
98	    %FILLING IN THE FLAGS
99	    out.flags=in.flags;
100	    out.flags.writtentostruct=1;
101	    out.flags.averaged=1;
102	
103	end
104	
