cat > /tmp/exp1.m <<'EOF'
warning('off','all');
addpath('/workspace/task/source/libraries/FID-A/inputOutput');
addpath('/workspace/task/source/sciencebench_task005');

% Build spectra from fixture (mirrors task005_evaluate)
dec = jsondecode(fileread('/workspace/task/fixtures/synthetic_edited_mrs_public.json'));
npts = dec.num_points;
ppm = linspace(dec.ppm_min, dec.ppm_max, npts)';
ref_shape = exp(-0.5*((ppm-dec.reference_center_ppm)/dec.reference_width_ppm).^2);
edit_shape = exp(-0.5*((ppm-dec.edited_center_ppm)/dec.edited_width_ppm).^2);
subs = length(dec.reference_amplitudes);
S = zeros(npts,subs);
for i=1:subs
  ph = dec.phase_degrees(i)*pi/180;
  sig = dec.reference_amplitudes(i)*ref_shape + dec.edited_amplitudes(i)*edit_shape;
  S(:,i) = real(sig*complex(cos(ph),sin(ph)));
end

% Write sdat (mirror task005)
in_dir = '/workspace/task/outputs/exp1';
mkdir(in_dir);
samples=npts; subspecs=subs; avgs=2;
rows_in_file=subspecs*avgs;
src=ifft(ifftshift(S,1),[],1);
fd=zeros(samples,rows_in_file);
for ai=1:avgs
  for si=1:subspecs
    fd(:,(ai-1)*subspecs+si)=src(:,si);
  end
end
packed=zeros(2,samples,rows_in_file);
packed(1,:,:)=real(fd); packed(2,:,:)=imag(fd);
dp=[in_dir '/e.sdat']; sp=[in_dir '/e.spar'];
fid=fopen(dp,'w','ieee-le'); fwriteVAXG(fid,packed(:),'float32'); fclose(fid);
fid=fopen(sp,'w');
fprintf(fid,'samples : %d\n',samples); fprintf(fid,'rows : %d\n',rows_in_file);
fprintf(fid,'averages : %d\n',rows_in_file); fprintf(fid,'synthesizer_frequency : 127731000\n');
fprintf(fid,'sample_frequency : 2000\n'); fprintf(fid,'echo_time : 68\n'); fprintf(fid,'repetition_time : 2000\n');
fprintf(fid,'scan_id : MEGA\n'); fprintf(fid,'scan_date : 2026.07.13\n');
fprintf(fid,'ap_size : 20\n'); fprintf(fid,'lr_size : 20\n'); fprintf(fid,'cc_size : 20\n');
fprintf(fid,'ap_off_center : 0\n'); fprintf(fid,'lr_off_center : 0\n'); fprintf(fid,'cc_off_center : 0\n');
fprintf(fid,'ap_angulation : 0\n'); fprintf(fid,'lr_angulation : 0\n'); fprintf(fid,'cc_angulation : 0\n');
fprintf(fid,'patient_position : HFS\n'); fprintf(fid,'patient_orientation : TRA\n'); fclose(fid);

L = io_loadspec_sdat(dp, subspecs, 0);
fids = L.fids;  % [samples x 1 x subspecs]
specs = L.specs;
fprintf('Loaded fids size: %s\n', mat2str(size(fids)));
fprintf('Loaded specs size: %s\n', mat2str(size(specs)));

% Reference mask
mask = abs(ppm-dec.reference_center_ppm) <= max(dec.reference_width_ppm*3.5,0.08);

function pol = polarity(sp)
  [~,i]=max(abs(real(sp)));
  pol = sign(real(sp(i))); if pol==0, pol=1; end
end

function report(tag, spec)
  w = real(spec(mask,:));
  p1=polarity(w(:,1)); p2=polarity(w(:,2));
