function ok = run(base,cid,npts,lo,hi,nsubs,refa,eda,phdeg)
  tag=sprintf('c%d',cid);
  [ppm,S,refc,refw]=build(npts,lo,hi,refa,eda,phdeg);
  [dp,sp]=write_sdat([base '/' tag '.sdat'],npts,nsubs,S,1);
  L=io_loadspec_sdat(dp,nsubs,0);              % default: undoPhaseCycle=1
  ok = check(L,ppm,refc,refw,nsubs) && valid(L,npts,nsubs);
  if ~ok, fprintf('  %s FAILED (default)\n',tag); end
end

function ok = run_preserve(base,cid,npts,lo,hi,nsubs,refa,eda,phdeg)
  tag=sprintf('p%d',cid);
  [ppm,S,refc,refw]=build(npts,lo,hi,refa,eda,phdeg);
  [dp,sp]=write_sdat([base '/' tag '.sdat'],npts,nsubs,S,1);
  % undoPhaseCycle=0 -> preserve original (180-inverted) subspectra
  L=io_loadspec_sdat(dp,nsubs,0,0);
  % Expected: the deliberately-inverted subspectrum is STILL inverted (distinct path)
  w = L.specs; if ndims(w)>2, w=squeeze(w); end
  if size(w,2)==1, w=w(:,1); end
  mask=abs(ppm-refc)<=max(refw*3.5,0.08);
  pol = cell(1,nsubs);
  for i=1:nsubs, pol{i}=polof(w(mask,i)); end
  consistent = all(pol{2:end}==pol{1});
  % For a 180-inverted input, preserving polarity means it is NOT made consistent:
  ok = valid(L,npts,nsubs) && (nsubs>1) && ~consistent && (pol{1} ~= pol{2});
  fprintf('  preserve %s: pols=[%s] consistent=%d ok=%d\n',tag, strjoin(cell2mat(pol),','),double(consistent),double(ok));
  if ~ok, error('preserve path failed'); end
end

function [ppm,S,refc,refw]=build(npts,lo,hi,refa,eda,phdeg)
  ppm=linspace(lo,hi,npts)';
  refc=3.02; refw=0.035; ec=2.28; ew=0.055;
  rs=exp(-0.5*((ppm-refc)/refw).^2); es=exp(-0.5*((ppm-ec)/ew).^2);
  nsubs=length(refa); S=zeros(npts,nsubs);
  for i=1:nsubs
    ph=phdeg(i)*pi/180;
    sig=refa(i)*rs+eda(i)*es;
    S(:,i)=real(sig*complex(cos(ph),sin(ph)));
  end
end

