function [ok,consist,ret]=check(L,ppm,refc,refw,nsubs)
  w=L.specs; if ndims(w)>2, w=squeeze(w); end
  if size(w,2)==1, w=w(:,1); end
  mask=abs(ppm-refc)<=max(refw*3.5,0.08);
  W=real(w(mask,:));
  n=columns(W);
  p=zeros(1,n); for i=1:n, p(i)=polof(W(:,i)); end
  consist=all(p==p(1));
  norms=zeros(1,n); for i=1:n, norms(i)=norm(W(:,i)); end
  ret=norm(mean(W,2))/max(mean(norms),1e-12);
  ok = consist && (ret>0.95) && all(isfinite(W(:)));
  fprintf('  check nsubs=%d consistent=%d retained=%.4f ok=%d\n',n,consist,ret,ok);
