function ok = run(base,cid,npts,lo,hi,nsubs,refa,eda,phdeg)
  tag=sprintf('c%d',cid);
  [ppm,S]=build(npts,lo,hi,refa,eda,phdeg);
  write_sdat([base '/' tag '.sdat'],npts,nsubs,S,2);
  dp=[base '/' tag '.sdat'];
  L=io_loadspec_sdat(dp,nsubs,0);
  ok = check(L,ppm,nsubs);
end

function ok = run_preserve(base,cid,npts,lo,hi,nsubs,refa,eda,phdeg)
  tag=sprintf('p%d',cid);
  [ppm,S]=build(npts,lo,hi,refa,eda,phdeg);
  write_sdat([base '/' tag '.sdat'],npts,nsubs,S,2);
  dp=[base '/' tag '.sdat'];
  L=io_loadspec_sdat(dp,nsubs,0,0);   % preserve original polarity
  ok = check_polarity(L,ppm,nsubs);
end

function [ppm,S]=build(npts,lo,hi,refa,eda,phdeg)
  ppm=linspace(lo,hi,npts)';
  refc=3.02; refw=0.035; ec=2.28; ew=0.055;
  rs=exp(-0.5*((ppm-refc)/refw).^2); es=exp(-0.5*((ppm-ec)/ew).^2);
  nsubs=length(refa); S=zeros(npts,nsubs);
  for i=1:nsubs
    ph=phdeg(i)*pi/180;
    sig=refa(i)*rs+eda(i)*es;
    S(:,i)=real(sig*complex(cos(ph),sin(ph)));
  end
end

function write_sdat(dp,npts,nsubs,S,avgs)
  sp=[dp(1:end-4) 'spar'];
  rows=nsubs*avgs;
  src=ifft(ifftshift(S,1),[],1);
  fd=zeros(npts,rows);
  for ai=1:avgs, for si=1:nsubs, fd(:,(ai-1)*nsubs+si)=src(:,si); end, end
  packed=zeros(2,npts,rows); packed(1,:,:)=real(fd); packed(2,:,:)=imag(fd);
  fid=fopen(dp,'w','ieee-le'); fwriteVAXG(fid,packed(:),'float32'); fclose(fid);
  fid=fopen(sp,'w');
  fprintf(fid,'samples : %d\n',npts); fprintf(fid,'rows : %d\n',rows); fprintf(fid,'averages : %d\n',rows);
  fprintf(fid,'synthesizer_frequency : 127731000\n'); fprintf(fid,'sample_frequency : 2000\n');
  fprintf(fid,'echo_time : 68\n'); fprintf(fid,'repetition_time : 2000\n'); fprintf(fid,'scan_id : MEGA\n');
