  fprintf(fid,'ap_off_center : 0\n'); fprintf(fid,'lr_off_center : 0\n'); fprintf(fid,'cc_off_center : 0\n');
  fprintf(fid,'ap_angulation : 0\n'); fprintf(fid,'lr_angulation : 0\n'); fprintf(fid,'cc_angulation : 0\n');
  fprintf(fid,'patient_position : HFS\n'); fprintf(fid,'patient_orientation : TRA\n'); fclose(fid);
end

function ok = check(L,ppm,nsubs)
  [spec,finite] = loaded_spec(L,nsubs);
  if ~finite, ok=false; fprintf('  non-finite!\n'); return; end
  mask=abs(ppm-3.02)<=max(0.035*3.5,0.08);
  W=real(spec(mask,:));
  n=columns(W);
  p=zeros(1,n); for i=1:n, p(i)=polof(W(:,i)); end
  consist=all(p==p(1));
  norms=zeros(1,n); for i=1:n, norms(i)=norm(W(:,i)); end
  ret=norm(mean(W,2))/max(mean(norms),1e-12);
  ok = consist && (ret>0.95) && all(isfinite(W(:)));
  fprintf('  check nsubs=%d consistent=%d retained=%.4f ok=%d\n',n,consist,ret,ok);
end

function ok = check_polarity(L,ppm,nsubs)
  [spec,finite] = loaded_spec(L,nsubs);
  if ~finite, ok=false; fprintf('  non-finite!\n'); return; end
  mask=abs(ppm-3.02)<=max(0.035*3.5,0.08);
  W=real(spec(mask,:));
  n=columns(W);
  p=zeros(1,n); for i=1:n, p(i)=polof(W(:,i)); end
  consistent=all(p==p(1));
  % preserve path keeps the deliberately-inverted subspectrum inverted
  ok = (n>1) && ~consistent && (p(1)~=p(2));
  fprintf('  preserve: pols=[%s] consistent=%d ok=%d\n', strjoin(num2str(p),','),double(consistent),double(ok));
end

function [spec,finite] = loaded_spec(L,nsubs)
  spec=L.specs;
  if ndims(spec)>2, spec=squeeze(spec); end
  if size(spec,2)==1, spec=spec(:,1); end
  finite = all(isfinite(L.fids(:))) && all(isfinite(L.specs(:)));
end

function p=polof(sp)
  [~,i]=max(abs(real(sp))); p=sign(real(sp(i))); if p==0,p=1;end
end
